Original:
```typescript
export function convertCents(amountCents: number, rateMicros: number): number {
  if (rateMicros <= 0) {
    throw new RangeError(`rate must be positive, got ${rateMicros}`);
  }
  return Math.round((amountCents * rateMicros) / 1_000_000);
}

```

